re_evidence": "HEADLINE FAIL: excess=-0.010 with CI entirely negative; state persistence does not clear the overlap null. No state-persistence paper.", "observed_sample_and_power": "N=1,060,893 possessions"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}, {"rel": "auto_related_family", "node": "FAM:SF-APPS-059"}]}, {"id": "FAM:SF-APPA-001", "label": "Study family SF-APPA-001: A1 adaptation falsification: asymmetry, confidence and carryover tests", "score": 0.485, "reached_via": ["FAM:SF-APPA-030 auto_related_family (limitation_precedent) FAM:SF-APPA-001", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.71); FAM:SF-APPA-001 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "A1 adaptation falsification: asymmetry, confidence and carryover tests", "auto_outcome_status": "artifact", "observed_hypothesis": "If the A1 adapter PPP lift is real coverage response, wrong-way teams should do worse than no-signal teams, the gap should widen with scheme-vote confidence, and adapting in Game N should carry over to Game N+1.", "observed_result": "T1 dPPP: adapter +0.0667 (n=205), neutral +0.0248 (n=50), no_signal +0.1260 (n=57), wrong_way +0.0111 (n=274). T2: adapter minus no-signal -0.0361 (1 vote), -0.1170 (2 votes). T3 next-game PPP Welch t=-1.003, p=0.842; MW [cut; read_family for the full text]", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_limited_by", "node": "LIM:selection_or_regression_to_the_mean"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}]}], "n_results": 10}

